            'traits' => ['Cenderung mempertanyakan alasan di balik kebiasaan atau kesimpulan.', 'Menyukai hubungan antara ide dari bidang yang berbeda.', 'Menghargai percakapan terbuka dan keleluasaan mencoba.'],
            'strengths' => ['Pengujian asumsi dapat membantu menemukan kelemahan gagasan sebelum diterapkan.', 'Keluwesan berpikir dapat membantu menghasilkan alternatif ketika pilihan pertama tidak bekerja.'],
            'challenges' => ['Memperdebatkan setiap pilihan dapat membuat rekan merasa pendapatnya tidak pernah cukup.', 'Ketertarikan pada ide baru dapat mengurangi perhatian pada rincian penyelesaian yang masih diperlukan.'],
            'communication' => ['Jelaskan tujuan pertanyaan Anda dan akui bagian gagasan orang lain yang bermanfaat.', 'Sepakati kapan diskusi perlu ditutup dan kondisi apa yang membolehkan keputusan dibuka kembali.'],
            'relationships' => ['Pertukaran ide dan rasa ingin tahu dapat menghidupkan hubungan.', 'Pastikan orang lain bersedia berdiskusi; mendengarkan pengalaman tidak selalu memerlukan sanggahan.'],
            'environment' => ['Kesempatan bereksperimen dan mempertanyakan cara kerja dapat terasa mendukung.', 'Batas ruang percobaan dan ukuran keberhasilan yang jelas dapat membantu mengarahkan eksplorasi.'],
            'stress' => ['Jika diskusi makin tajam, berhenti sejenak dan pastikan masalah yang sebenarnya sedang dibahas.', 'Saat banyak ide terbuka, pilih satu yang dapat diuji dengan biaya dan waktu terbatas.'],
